function solve({config,state,event}) {
  let s = Array.isArray(state) ? state : [];
  const copy = a => a.slice();
  const sum = a => { let n=0; for(let i=0;i<a.length;i++) n=(n+(i+1)*a[i])%251; return n; };
  const type = event && event.type;
  if(type === 'save') {
    const id=event.id;
    let k=s.findIndex(x=>x.id===id);
    if(k>=0) s.splice(k,1);
    s.push({id:id,data:copy(event.data),checksum:event.checksum});
    while(s.length>config.keep) s.shift();
  } else if(type === 'damage') {
    const x=s.find(x=>x.id===event.id);
    if(x && Number.isInteger(event.index) && event.index>=0 && event.index<x.data.length) x.data[event.index]=event.value;
  } else if(type === 'drop') {
    const k=s.findIndex(x=>x.id===event.id);
    if(k>=0) s.splice(k,1);
  } else if(type === 'restore') {}
  let data=null, chosen=null;
  if(type === 'restore') {
    for(let i=s.length-1;i>=0;i--) if(sum(s[i].data)===s[i].checksum){data=copy(s[i].data);chosen=s[i].id;break;}
  }
  return {state:s,output:{data:data,chosen:chosen,retained:s.map(x=>x.id)}};
}
